          "text": "第一に、想像界の人類学的構造をみると、ジルベール・デュランは、西洋において想像力の産物とされる説話、物品などあらゆる事実が決して地水火風の構造を逸脱しないことを発見し、これを想像界の人類学的構造と名付けた。[4] 数多くの説話と発明品は、結局「地水火風」のような循環のセレンディピティから生まれるというのである。"
