          "type": "p",
          "text": "セレンディピティは既存の方法を積極的に活用する。地水火風が類比的思惟に関わる西洋のセレンディピティ技法であるとすれば、陰陽五行は地水火風よりも発展した東洋の類比的セレンディピティ技法であるといえる。陰陽五行は長い歴史の中でセレンディピティと関連して、陰陽五行に両義的な判断を与えうる。さらに現代人が知らない類比的思惟の無限の宝庫となりうる。"
