          "text": "生存当時、アリストテレスと比較されるほど尊崇を受けていたエンペドクレスの質料中心の四元素説を、アリストテレスは独自の実体論によって形相中心の形式的理論へと転換した。質料中心の四元素説では質料が自ら運動して循環するのに対し、形相中心の四元素は固定されて循環しない。今日、アリストテレスの四元素説は近代科学によって否定されたが、エンペドクレス以前の四元素説は、バシュラールが示すように様々な形で復活を遂げている。地水火風もまた第5元素に言及したが、陰陽五行における土ほど、宇宙における人間の位置を示す要素はない。[9] このような点で、火山の噴火により大地全体が焼けた済州では、土地を焼きながら農耕を行う焼畑農業が効果的な農法であった。[10]"
