          "text": "始皇帝に関する歴史的事実が徐々に発掘されるにつれ、徐福が済州島と持つ関係についても新たな理論が登場している。済州文化の起源と徐福に関する新たな解釈も、三姓穴の神話を徐福と結びつけて探っている。[14] 三姓穴を東北アジア全体にわたる説話の延長線上で解釈する既存の解釈は[15]、逆説的に徐福と三姓穴の愛の物語が東北アジア全体の愛であったことを示している。徐福に関する新たな解釈には、三姓穴の高・夫・良という三姓が当時中国にのみあった姓であり、この三姓は徐福が第一次遠征で日本へ向かう前に落伍した三人の姓であったとするものがある。三姓穴を徐福と初めて結びつけたホン・スンマン前徐福学会会長の後を継ぎ、同一の主題を研究する西帰浦市徐福文化国際交流協会のウ・ギュイルによれば、徐福は本格的な集団移住を企図した第二次遠征に成功し、この時、日本から済州に残しておいた三人のために三人の王女を送ったのが婚姻池の伝説であるという。[16] ウ・ギュイルは、韓国で発行されている中国人民政府機関紙『金橋』の2012年4月号に論文を掲載した後、「婚姻池」の伝説を主な内容とする徐福のテレビ大河ドラマ制作を日中韓合作で進めていたが、日本の再軍備をめぐる国際紛争により現在中断中であるという。"
