          "type": "p",
          "text": "済州島において三神山が持つ愛と幸運のセレンディピティは、トルハルバンに至って宇宙的な次元にまで拡大される。まるで宇宙の守護者にして使者のような感じを与えるトルハルバンは、済州島が神々と人間に幸運をもたらす場所であり、世界のどこにも済州ほど神と親しい土地はないことを示している。神はもはやタブー視される存在ではない。死とも親しむことができる場所、死ぬ前に最も見たいと言われる空を見ることができる場所、それが済州島である。天と地は古来、宇宙と自然が運行される陰陽の代表物であった。空を愛する人は済州の空を決して忘れることができない。済州を一度訪れた人がこの理を知れば、必ずまた済州を訪れることになる。"
