          "text": "空との関わりから済州をもう一度再解釈してみよう。済州には実際に天の川、宇宙、太極と関わる説話や地名がある。漢拏山が三神山と関連して陸地とつながっていることに着目し、済州島は雛（ひよこ）に例えられることもある。実際に済州島の地図を見ると、馬羅島が手前の山房山とともに雛の口となり、城山日出峰と牛島は雛の尾となる。済州島は実際に雛の色と同じ菜の花とミカンの特産地である。済州島が雛のような姿をしているということは、済州島が三神山の長兄格である金剛山のユートピアである天へ昇る機能と関連していることを示している。済州島のトルハルバンもまた愛のアイコンである。済州島のトルハルバンは、済州を代表するハルマンの恋人でもある。"
