          "type": "p",
          "text": "甑（蒸し器）の形をした山なので甑山と呼んだのは、太平洋の水を注いでも溢れないほどの大きな器であるがゆえに天の川を引き寄せることができる山という意味の「漢拏山」に相応しい名である。白鹿潭は天の川を象徴しているかのようである。甑は米の特性をそのまま活かしながら一つにまとめる働きをするので、韓国人の特性をよく説明してくれる。また、この山には韓国で最も標高の高い国道である99号線が標高1100メートル以上の高地を走っているが、懐が広いため、人々に高くありながらも安らぎを与える聖人のような印象を与える。"
