          "type": "p",
          "text": "済州島博物館を訪れると、済州島の日常に表れた創造性を見ることができる。東洋思想は時間の変化を人の一生と一致させて表現してきたが、済州博物館でも時間の変化を人の一生として一目瞭然に示している。済州島では人間の一生を奇字山神、アギグドク（子守り籠）、童心、婚礼として表現する。これは東洋思想において人間の一生を、子を身ごもる胞胎、母の胎内で育つ養生、生まれた子を沐浴させる浴帯、成長した子を結婚させる冠旺に分類したのと同じ理である。ここでアギグドクは済州島らしい時間の知恵を最もよく示している。"
