          "text": "西洋の場合、ウンベルト・エーコの小説『薔薇の名前』が示したように、西洋は笑いに代表される共感に対して極度に統制してきた歴史を持つ。東洋で発生した四大宗教はいずれも共感を倫理の源泉としているが、旧約聖書に由来する西洋の伝統は、共感を徹底して排斥すべき感情とみなした。共感あるいは感応の排除は、キリスト教の禁欲的原理と結びついた。"
