          "text": "上の写真は済州島の山房山である。済州島は変化の力が強いとされ、周辺諸国は早くからその変化の脈を絶とうとした。山房山は済州島の中でも特に「三」の理を持っている。山房山の土窟は三機能体系の国々に共通する修行の場を示しており、[115]山房山の三つの峰は、まるで三神山を一か所にまとめ、儒・仏・道を合わせたかのようである。実際、山房山には神仙になれるという仙官岩もある。"
