              "n": "28",
              "text": "余裕とは、物質的、時間的、そして空間的に十分な状態、あるいは落ち着いて穏やかな心の状態を言う。ここでは空間的次元の余裕を除き、物質的・時間的・精神的余裕に重点を置いて考察した。"
