          "type": "p",
          "text": "済州島は、実際に最も美しい景観に劣らず、最も強烈な苦難克服の歴史と文化を持っている。そのためには、済州島が築き上げてきた文化の価値を、現代人にも理解できるようにしなければならない。そして、その根底には済州文化に対する自尊感の回復が必要である。さらに進んで、観光は観光として育てなければならない。観光とは西洋でいうように見て楽しむものではない。光（光）を求めて学ぶことである。言い換えれば、輝かしい業績を積んだ人を訪ね、貫き通すほど詳細に見つめること〔観（觀）〕である。今や済州島は、時代と空間が求める要請に従って変わらなければならない。例えば、済州島の観光は、私を癒し、あなたを癒す癒しの観光へと変わることもできる。また、済州島を道徳君子の島へと変化させることもできる。それゆえ、済州島は韓国で最も倫理的な地域の一つへと成長することもできる。他の地域と異なり、悪事を働いても逃げる場所がないという島の長年の特徴と、清らかな自然を媒介として、これを実現することができるからである。"
