          "text": "それでは、済州島の地理的特徴を根拠に、共感と類比的思惟を適用した済州文化の拡大について、より具体的に考えてみよう。例えば、済州島の地形に風水学的なストーリーテリングを加えて、済州島全体を一つの文化遺産にすることもできるだろう。[14] オルレ道でも有名な済州島だが、済州島にはオルレ道よりも大きな自然の知恵を含んだ「水の道」と「火の道」があるとも見ることができる。もちろん、これはすでに何人かによって取り上げられたこともある。本稿でも、これを共感と類比的思惟による済州文化の拡大という側面から、水の道と火の道として先に提示した。[15]"
