          "text": "済州文化の実存的・構造的分析で述べたように、島であることは、孤立的な性格と進出が容易であるという性格を、ともに備えている。文化が繁栄するときには進出が容易となり世界文化の中心となるが、文化が沈滞するときには孤立し、周囲の視線を受けられなくなる。こうした事件の前後には偶然的な要素が存在し、これをどう活用するかによって、セレンディピティとしての成功の可否が決まるということである。また、韓国という半島文化に根を下ろしながらも、境界をなす日本の海洋文化、中国の大陸文化を共有しているという点も同様である。やはり、自らの文化がどのような力量を持っているかによって、済州文化の位置と評価は変わりうる。"
