          "text": "また、島は女性が多く、女性が中心となる文化を形成した。例えば、金萬徳は韓国史上、平民の身分でありながら寄付を通じて国に大きな功績を残した女性となった。今やこれをさらに創造的に発展させるべきである。韓国の発展も結局は女性の活用にかかっているため、これを済州文化から創造的に提示することもできる。また、クェンダン文化と呼ばれるように、最も共同体が発達した文化を築いた。"
