              "text": "済州の歴史は、絶えざる内陸からの収奪とその克服の歴史であるといえる。(玄容駿『済州島の人々の暮らし』民俗苑、2009年、20-51頁) しかし、チンギス・ハンから経営の方法を学ぶことが一時流行したように、『海女のように経営せよ』という本を著したチョン・ギョンイルは、済州の海女からチンギス・ハンに劣らぬ民俗経営学を学び得ると述べている。(チョン・ギョンイル『海女のように経営せよ』ダヴィンチブックス、2010年)"
