    {
      "id": "afterword",
      "title": "あとがき",
      "blocks": [
        {
          "type": "p",
          "text": "本書は、これまで研究してきた世界を分析する枠組みに関する研究、文化研究、地域学研究を融合させて完成させたものである。世界を分析する枠組みとは、哲学を基礎として世界を理解し、世界の原理を把握しようとする研究に集約されるが、本書ではすでに知られている理論をひとまず脇に置き、新たな見解と研究に耳を傾け、用いてみた。また、日常文化と地域文化を含む多様な文化研究、中国と韓国を中心に進めてきた地域学研究などを基礎とした。"
        },
        {
          "type": "p",
          "text": "本文では、これまで研究してきた資料を活用した。特に、筆者らが共同研究して発表した「人文学の危機に対する私・此処・今を中心とした実存的アプローチ」（『人文研究』69号、嶺南大学校、2013年）、「先秦儒家に現れた共感としての私・此処・今」（『儒教思想文化研究』54号、韓国儒教学会、2013年）、「先天易学に現れた共感としての私・此処・今」（『儒教思想文化研究』56号、韓国儒教学会、2014年）、「済州島文化の分析・拡大・創造に関する多角的考察」（『人文研究』71号、嶺南大学校、2014年）であり、いずれも学術研究財団の登載学術誌である。また、本文で言及した文化と創造の部分は、既刊の『文化の受容と創造』から引用した。本書には以上の研究成果の一部内容が含まれているが、多くの内容を新たに構成した。"
        },
        {
          "type": "p",
          "text": "既存の研究を土台に、文化の見方をより具体的に進めたいと考えた。韓国の文化、その中でも特徴的な性格を持ちながら、日常的な文化を持つ文化を扱いたかった。そこで、枠組みは既存のものを用いながら、その中に具体的な文化として済州島の文化を盛り込んだ。済州島の文化は、韓国に属しながらも韓国とは異なる性格を持つ文化である。開放的でありながら閉鎖的な文化であり、島の文化でありながら大陸の文化を持ち、伝統の文化を維持しながらも未来の文化を発見できる文化である。それゆえ多様であり、それゆえ希望に満ちている。"
        },
        {
          "type": "p",
          "text": "このような済州島の文化を盛り込むためには、新たな何かが必要であった。何と言おうか。既存の研究を包摂しながらも差別化され、しかも新たな霊感を提供しうるもの。それを我々はセレンディピティと見た。そしてここに共感理論と共通パターンを加えた。"
        },
        {
          "type": "p",
          "text": "実のところ、筆者のうち一人は済州島についてあまりよく知らない。そしてもう一人は非常によく知っている。このような調和が済州島に対する創意的な発想を生み出すであろうと期待した。よく知らない不慣れさから来る客観的な評価と批判、よく知っている親しさから来る補完と現実的な提示。既存とは異なり、拙く粗削りであり、また誤りうるものでもあるが、既存の済州島関連の研究や書籍を分析しながら、いつも同じことを繰り返す済州紹介書ではない、何か新しい枠組みと方法で見てみたかった。"
        },
        {
          "type": "p",
          "text": "今もなお絶えず人文学的実験を試みている。これまで既存の理論とは異なり新しい、あるいは主流学界では等閑視されてきた理論を検討しながら融合させようとしてきた。学校にいる一人は平穏の垣根の中で怠惰であるが、平穏の垣根を蹴り飛ばしたもう一人は、飢えたハイエナのように新たな学問と研究のためにすべてを捨てて身を投じている。"
        },
        {
          "type": "p",
          "text": "膨大な内容と多様な理論のすべてにおいて、二人の合意を得ることはできない。そして今後も無理に辻褄を合わせるつもりはない。読者にもぴったりと合わせたものを投げ与えてきた既存のやり方から、余白を残す方式へと接近していくつもりである。その残りは、我々の現在の力量では埋めきれず、より創意的な読者と後学、そして我々の進化する研究が満たし、埋めていくであろう。"
        },
        {
          "type": "p",
          "text": "これからも挑戦し続けるつもりである。我々が研究する対象も生きた生物のようであるが、研究して生み出す成果物もまた生きた生物のようであり、変化し発展していくであろう。それゆえ、「我々が成し得たことと同じくらい、成し得なかったことも誇りに思う I'm as proud of what we don't do as I am of what we do. (Steve Jobs)」と言えるようになるまで、最善の努力を尽くすつもりである。"
        },
        {
          "type": "p",
          "text": "この本を作るにあたって助けてくださった多くの恩人に感謝申し上げる。済州発展研究院をはじめ、乏しい状況の中で助けてくれた家族、そして著作権の使用を許してくださった方々、出版のために尽力してくださった先生方など、すべての方に頭を下げて深く感謝の意を伝える。より良い研究成果をもって恩返ししたい。"
        }
      ]
    }
